!function(e){function t(t){for(var p,i,o=t[0],m=t[1],s=t[2],d=0,g=[];d<o.length;d++)i=o[d],Object.prototype.hasOwnProperty.call(n,i)&&n[i]&&g.push(n[i][0]),n[i]=0;for(p in m)Object.prototype.hasOwnProperty.call(m,p)&&(e[p]=m[p]);for(c&&c(t);g.length;)g.shift()();return a.push.apply(a,s||[]),r()}function r(){for(var e,t=0;t<a.length;t++){for(var r,i=a[t],o=!0,m=1;m<i.length;m++)r=i[m],0!==n[r]&&(o=!1);o&&(a.splice(t--,1),e=p(p.s=i[0]))}return e}function p(t){if(i[t])return i[t].exports;var r=i[t]={i:t,l:!1,exports:{}};return e[t].call(r.exports,r,r.exports,p),r.l=!0,r.exports}var i={},n={55:0},a=[];p.m=e,p.c=i,p.d=function(e,t,r){p.o(e,t)||Object.defineProperty(e,t,{enumerable:!0,get:r})},p.r=function(e){"undefined"!=typeof Symbol&&Symbol.toStringTag&&Object.defineProperty(e,Symbol.toStringTag,{value:"Module"}),Object.defineProperty(e,"__esModule",{value:!0})},p.t=function(e,t){if(1&t&&(e=p(e)),8&t)return e;if(4&t&&"object"==typeof e&&e&&e.__esModule)return e;var r=Object.create(null);if(p.r(r),Object.defineProperty(r,"default",{enumerable:!0,value:e}),2&t&&"string"!=typeof e)for(var i in e)p.d(r,i,function(t){return e[t]}.bind(null,i));return r},p.n=function(e){var t=e&&e.__esModule?function(){return e.default}:function(){return e};return p.d(t,"a",t),t},p.o=function(e,t){return Object.prototype.hasOwnProperty.call(e,t)},p.p="";var o=window.webpackJsonp=window.webpackJsonp||[],m=o.push.bind(o);o.push=t,o=o.slice();for(var s=0;s<o.length;s++)t(o[s]);var c=m;a.push([162,0]),r()}({162:function(e,t,r){"use strict";r.r(t);var p=r(0);Object(p.a)("de","army",r(163),r(1))},163:function(e){e.exports=JSON.parse('{"category":[{"name":"德国","link":"de_shortcut"},{"name":"陆战武器","link":"de_army"},{"name":"军用小车","link":"de_army#de_army_mts"}],"model":"大众军用小车","description":"<p>二战期间，德军拥有不少的军用小车，这些军用小车除一部分作军官座驾外，还有不少军用小车担负着运兵、救护、火炮牵引和命令传送等任务。这些军用小车生产厂家有大众（VW）、霍希（Horch）、斯太尔（Steyr）、奔驰（Benz）和宝马（BMW）等等，型号众多，虽然这些军用小车没有装甲防护，大多也没有武器装备，但它们有着功能多样性与极高的机动性，它们不属战场的直接战斗车辆，但也是德军在二战中一种重要的机动力量。</p><p>VW82型军用小车（有称VW82桶车）和VW166型两栖军用小车（也有称VW166型桶车）是德国大众公司在二战中生产的两种有名越野车，其中VW82型军用小车在二战期间就生产了52000多辆，是德军在二战中拥有数量众多的军用越野车之一。大众军用小车最大特点是轻巧，结构简单可靠，机动性好，因此广受德军的喜爱。</p><p>二战中，这些VW82军用小车大量配备给德国陆军的侦察与通信部队，也是不少德军中下级军官使用的专车。而VW166型两栖军用小车则是一种水陆两用的越野车，该车适用于在河网密集交错的地区行驶，VW166型两栖军用小车在1942年底投产，但生产数量并不多，大多装备给德国党卫军部队使用。</p>","part1title":"主要型号","part1description":"","part1content":[{"image":"imgs/de/army/de_army_mtsVW_11.jpg","description":"<h6>大众VW82军用小车（桶车）</h6><p>二战前的1936年，大众公司就已经生产出一种型号为VW60型小汽车，为了满足德军在即将开始的战争对机动车辆的需求，1938年底，大众在VW60基础上进行了提升改进，生产出VW62型样车，后因该型车越野性能不理想，于是又对VW62作了底盘升高等改进，定型为VW82型，于1940年开始量产。</p><p>由于VW82军用小车使用了风冷式发动机，所以即使是寒冷的苏联战场，或是炎热的非洲战场，该小车发动机都能可靠地工作，而它的独立悬挂系统也使小车具备良好的操作性能和更好的越野能力。在1939年入侵波兰的行动中，VW82小车就显示了优良的机动与越野性能。</p><p>技术参数：</p><p>车长：3.73米，车宽：1.6米，车高：1.65米，车重：0.725吨；</p><p>有效载荷：0.45吨；</p><p>发动机：VW/4缸汽油机，最大功率：23.5马力；油箱油量：40升；</p><p>最高时速：80公里/小时；</p><p>公路最大行程（满载油缸）：440公里。</p>","caption":""},{"image":"imgs/de/army/de_army_mtsVW_18.jpg","description":"<h6>大众VW166型两栖军用越野车</h6><p>大众VW 166型两栖军用越野车是在VW82型的基础上开发的一种可在陆地和河湖中行驶的军用小车，该车的轴距更短，重量更轻，车后安装了螺旋浆作水中行驶的驱动。</p><p>技术参数：</p><p>车长：3.825米，车宽：1.48米，车高：1.615米，车重：0.91吨；</p><p>有效载荷：0.435吨；</p><p>发动机：VW/4缸汽油机，最大功率：25马力；油箱油量：2X25升；</p><p>最高时速：80公里/小时，水中行驶时速：10公里/小时；</p><p>公路最大行程（满载油缸）：520公里。</p>","caption":""}],"part2title":"战场上的大众军用小车","part2description":"","part2content":[{"image":"imgs/de/army/de_army_mtsVW_12.jpg","description":"号称“非洲之星”的二战德国空中英雄马尔塞尤与他的大众VW82座驾。","caption":""},{"image":"imgs/de/army/de_army_mtsVW_13.jpg","description":"1944年9月，西线战场荷兰阿纳姆地区，隶属德国武装党卫军第9“霍亨施陶芬”装甲师的一辆大众VW82 Kfz 2军用小车。","caption":""},{"image":"imgs/de/army/de_army_mtsVW_14.jpg","description":"1943-1944年冬季，东线苏联战场，德军“大德意志”装甲掷弹兵师救护部队的一辆大众VW82 Kfz 2军用小车。","caption":""},{"image":"imgs/de/army/de_army_mtsVW_15.jpg","description":"1942年，北非战场利比亚，德军非洲军团第164轻装师的一辆用大众VW82 Kfz 2军用小车改装的救护车。","caption":""},{"image":"imgs/de/army/de_army_mtsVW_16.jpg","description":"这是大众公司专门为德国非洲军团生产的一种非洲版的VW82军用小车，它在原VW82的基础上改装了适合于沙漠行驶的轮胎。在1942年的北非战场上，VW82军用小车以其在恶劣沙漠环境中的出色表现得到了德国非洲军团司令官隆美尔的赞赏。","caption":""},{"image":"imgs/de/army/de_army_mtsVW_17.jpg","description":"装载在大型运输机中的德军一辆大众VW82 Kfz 2军用小车，由于VW82军用小车十分轻巧，所以无论是海、陆、空运输都是十分方便。","caption":""},{"image":"imgs/de/army/de_army_mtsVW_19.jpg","description":"在水中行驶的大众VW166型两栖军用越野车。（绘图）","caption":""},{"image":"imgs/de/army/de_army_mtsVW_20.jpg","description":"1943年秋天，东线苏联战场，隶属德国武装党卫军第8“弗洛里安·盖尔”骑兵师的一辆大众VW166 Kfz 2/1型两栖军用越野车。","caption":""},{"image":"imgs/de/army/de_army_mtsVW_21.jpg","description":"1943年未，西线战场法国，隶属德国武装党卫军第9“霍亨施陶芬”装甲师第9党卫军装甲炮兵团的一辆大众VW166型两栖军用越野车。","caption":""},{"image":"imgs/de/army/de_army_mtsVW_22.jpg","description":"1944年，一辆在陆地行驶的大众VW166 Kfz 2/1型两栖军用越野车，车上坐着德军“大德意志”机械化步兵团一名上校军官（前）和“大德意志”装甲营一名少校军官（后）。","caption":""},{"image":"imgs/de/army/de_army_mtsVW_23.jpg","description":"一辆在水中行驶的大众VW166 Kfz 2型两栖军用越野车，注意车辆侧面的印刷框中有该型车的技术数据。","caption":""},{"image":"imgs/de/army/de_army_mtsVW_24.jpg","description":"1944年东线战场，在一辆在前线的德军大众VW166 Kfz 2型两栖军用越野车，车上的军官正在观察前方状况。","caption":""}]}')}});